// Shared game data: used by both the Node server (require) and the browser client (script tag).
(function (root, factory) {
  if (typeof module === 'object' && module.exports) module.exports = factory();
  else root.SHARED = factory();
})(typeof self !== 'undefined' ? self : this, function () {

  const PHYS = {
    TICK: 1 / 60,
    GRAV: 2400,
    FASTFALL: 1.55,
    MAX_FALL: 1500,
    FRICTION: 2600,
    HITSTUN_FRICTION: 400,
    BODY_W: 52,
    BODY_H: 96,
    RESPAWN_DELAY: 1.6,
    RESPAWN_INVULN: 2.5,
