  // Attack fields: dmg (%), baseKb / kbScale (knockback px/s), angle (radians above
  // horizontal), startup/active/recover (seconds), range/height (hitbox in front of fighter).
  const CHARACTERS = {
    blaze: {
      name: 'BLAZE', tagline: 'The Burning Fist',
      speed: 470, airAccel: 2100, airSpeed: 440, jumpVel: 900, jumps: 2, weight: 0.92,
      skin: '#e8a87c', color1: '#ff4422', color2: '#ffaa00', accent: '#ffe066', trail: '#ff6633',
      attacks: {
        jab:   { dmg: 7,  baseKb: 230, kbScale: 7.0,  angle: 0.40, startup: 0.07, active: 0.10, recover: 0.15, range: 80,  height: 60 },
        smash: { dmg: 14, baseKb: 430, kbScale: 11.5, angle: 0.65, startup: 0.20, active: 0.13, recover: 0.28, range: 100, height: 80 }
      }
    },
    titan: {
      name: 'TITAN', tagline: 'The Living Mountain',
      speed: 340, airAccel: 1500, airSpeed: 330, jumpVel: 820, jumps: 2, weight: 1.30,
      skin: '#b9c2a8', color1: '#5b6f52', color2: '#8d9b7a', accent: '#d8c27a', trail: '#9bab86',
      attacks: {
        jab:   { dmg: 10, baseKb: 290, kbScale: 8.0,  angle: 0.35, startup: 0.12, active: 0.11, recover: 0.22, range: 88,  height: 70 },
        smash: { dmg: 19, baseKb: 520, kbScale: 13.5, angle: 0.80, startup: 0.30, active: 0.14, recover: 0.38, range: 110, height: 95 }
      }
    },
    volt: {
      name: 'VOLT', tagline: 'The Storm Runner',
      speed: 520, airAccel: 2400, airSpeed: 500, jumpVel: 980, jumps: 3, weight: 0.82,
      skin: '#f2d6b3', color1: '#ffd400', color2: '#2196f3', accent: '#ffffff', trail: '#ffe34d',
      attacks: {
        jab:   { dmg: 5,  baseKb: 200, kbScale: 6.2,  angle: 0.45, startup: 0.05, active: 0.09, recover: 0.12, range: 74,  height: 56 },
        smash: { dmg: 11, baseKb: 380, kbScale: 10.5, angle: 0.95, startup: 0.16, active: 0.12, recover: 0.24, range: 90,  height: 90 }
      }
    },
    shade: {
      name: 'SHADE', tagline: 'The Silent Blade',
      speed: 440, airAccel: 2000, airSpeed: 430, jumpVel: 920, jumps: 2, weight: 0.95,
      skin: '#cdb4d6', color1: '#3a2a5d', color2: '#7b4dff', accent: '#c3f53b', trail: '#8f6bff',
      attacks: {
        jab:   { dmg: 6,  baseKb: 220, kbScale: 6.8,  angle: 0.30, startup: 0.06, active: 0.11, recover: 0.14, range: 104, height: 58 },
        smash: { dmg: 13, baseKb: 410, kbScale: 11.0, angle: 0.55, startup: 0.19, active: 0.14, recover: 0.26, range: 130, height: 78 }
      }
    }
  };

  // World coords: origin at stage center, +y is down. Platforms are one-way (land from above).
  const MAPS = {
    skylands: {
      name: 'SKY SANCTUARY', tagline: 'Floating ruins above the clouds',
      platforms: [
        { x: -460, y: 210, w: 920, h: 44, main: true },
        { x: -360, y: 30,  w: 240, h: 18 },
        { x: 120,  y: 30,  w: 240, h: 18 },
        { x: -120, y: -140, w: 240, h: 18 }
      ],
      spawns: [[-330, 180], [330, 180], [-240, 0], [240, 0]],
      blast: { left: -1150, right: 1150, top: -850, bottom: 720 }
    },
    flatline: {
      name: 'NEON GRID', tagline: 'No platforms. No mercy.',
      platforms: [
        { x: -560, y: 230, w: 1120, h: 48, main: true }
      ],
      spawns: [[-420, 200], [420, 200], [-140, 200], [140, 200]],
      blast: { left: -1200, right: 1200, top: -850, bottom: 700 }
    },
    volcano: {
      name: 'EMBER PEAKS', tagline: 'Three islands over a sea of fire',
      platforms: [
        { x: -620, y: 150, w: 380, h: 40, main: true },
        { x: -170, y: 250, w: 340, h: 40, main: true },
        { x: 240,  y: 150, w: 380, h: 40, main: true },
        { x: -120, y: 20,  w: 240, h: 18 }
      ],
      spawns: [[-430, 120], [430, 120], [0, 220], [0, -40]],
      blast: { left: -1150, right: 1150, top: -850, bottom: 700 }
    }
  };

  return { PHYS, CHARACTERS, MAPS };
});

